//! The compiled-in tables of g-xTB, per version: [`v1_1`] (the 1.1.0 program's tables, decoded
//! from its binary), [`v2_0_1`] (the 2.0.1 parameter tables, generated by
//! `crates/gxtb/scripts/make_data_v2.py`), [`runtime`] (tables the 1.1.0 program computes at
//! run time, extracted under gdb) and [`qvszp`] (the q-vSZP basis file `param/basisq`, generated
//! by `crates/gxtb/scripts/make_qvszp_table.py`). The parsed parameter files of v1.1 are
//! [`crate::params`].

#[rustfmt::skip] // parameter tables keep their compact layout
pub mod qvszp;
#[rustfmt::skip] // parameter tables keep their compact layout
pub mod runtime;
#[rustfmt::skip] // parameter tables keep their compact layout
pub mod v1_1;
#[rustfmt::skip] // parameter tables keep their compact layout
pub mod v2_0_1;
